<main class="section"><div class="admin-page-intro"><div><span class="eyebrow">Fristen</span><h1>Was läuft wann ab?</h1><p>Alle relevanten Auftrags-, Nachweis-, Versand- und Angebotsfristen nach Dringlichkeit.</p></div><a class="btn ghost" href="/admin">Zur Übersicht</a></div>
<form method="get" class="filter-bar"><select name="bucket"><option value="">Alle Zeiträume</option><option value="overdue" <?=$filterBucket==='overdue'?'selected':''?>>Überfällig</option><option value="today" <?=$filterBucket==='today'?'selected':''?>>Heute</option><option value="tomorrow" <?=$filterBucket==='tomorrow'?'selected':''?>>Morgen</option><option value="later" <?=$filterBucket==='later'?'selected':''?>>Später</option></select><input name="type" value="<?=App\Core\View::e($filterType)?>" placeholder="Nach Fristart suchen"><button class="btn">Filtern</button></form>
<div class="worklist"><?php foreach($items as $i):?><a class="work-row" href="<?=App\Core\View::e($i['url']??(!empty($i['order_id'])?'/admin/auftraege/'.$i['order_id']:'/admin/angebote'))?>"><div><b><?=App\Core\View::e($i['type'])?> · <?=App\Core\View::e($i['title'])?></b><span>Fällig <?=date('d.m.Y H:i',strtotime($i['due_at']))?><?php if(!empty($i['grace_at'])):?> · Nachfrist <?=date('d.m.Y H:i',strtotime($i['grace_at']))?><?php endif;?></span></div><strong><?=App\Core\View::e($i['escalation'])?></strong></a><?php endforeach;?><?php if(!$items):?><div class="empty">Für diesen Filter gibt es keine offenen Fristen.</div><?php endif;?></div></main>